"""Render the bilingual, progressively enhanced download gallery."""
from html import escape
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def size(n):return f'{n/1048576:.1f} MB' if n>=1048576 else f'{n/1024:.0f} KB'
def gallery(lang):
 zh=lang=='zh';items=json.loads((ROOT/'content/resources.json').read_text());labels={'all':'全部' if zh else 'All resources','template':'模板' if zh else 'Templates','texture':'纹理' if zh else 'Textures','lut':'调色预设' if zh else 'LUTs'}
 pack='/downloads/photocraft-starter-collection.zip';packsize=size((ROOT/'dist'/pack.lstrip('/')).stat().st_size)
 controls=''.join(f'<button type="button" data-resource-filter="{k}" aria-pressed="{str(k=="all").lower()}">{v}'+(' · 14' if k=='all' else ' · '+str(sum(x['kind']==k for x in items)))+'</button>' for k,v in labels.items())
 cards=[]
 for i in items:
  downloads=''.join(f'<a class="asset-download" href="{d["url"]}" download aria-label="{escape(i["title"][lang])} — {d["label"]} ({size(d["bytes"])})">↓ {d["label"]} <span>{size(d["bytes"])}</span></a>' for d in i['downloads'])
  spec=(f'{i["width"]} × {i["height"]} px · {i["layers"]} '+('像素图层' if zh else 'pixel layers')) if i['kind']=='template' else (f'{i["width"]} × {i["height"]} px' if i['kind']=='texture' else ('17³ · 常规 RGB 照片' if zh else '17³ · standard RGB photos'))
  note=({'template':'PSD 示例文字已栅格化；隐藏该层后输入新文字。','texture':'作为背景图层使用，可调整不透明度与大小。','lut':'预览为程序生成色卡，不是 PhotoCraft 应用截图。'} if zh else {'template':'PSD sample text is rasterized. Hide it and add your own type.','texture':'Use as a background layer; adjust opacity and scale.','lut':'Preview: generated color chart, not a PhotoCraft app screenshot.'})[i['kind']]
  cards.append(f'''<article class="asset-card" data-resource-kind="{i['kind']}" data-resource-search="{escape((i['title'][lang]+' '+i['description'][lang]+' '+i['format']).lower(),quote=True)}"><div class="asset-preview"><img src="{i['preview']}" alt="{escape(i['title'][lang])} — {'资源预览' if zh else 'asset preview'}" width="{i['width']}" height="{i['height']}" loading="lazy" decoding="async"></div><div class="asset-content"><span class="overline">{labels[i['kind']]} / ORIGINAL</span><h2>{escape(i['title'][lang])}</h2><p>{escape(i['description'][lang])}</p><div class="asset-spec">{spec}</div><p class="asset-note">{note}</p><div class="asset-downloads">{downloads}</div></div></article>''')
 return f'''<section class="asset-library" aria-label="{'资源下载库' if zh else 'Download library'}"><div class="asset-bundle"><div><div class="overline">STARTER COLLECTION / V1.0</div><h2>{'14 份原创资源，开始你的下一个作品。' if zh else '14 original assets. Your next project starts here.'}</h2><p>{'6 套分层模板 · 4 款 PNG 纹理 · 4 款 CUBE 预设' if zh else '6 layered templates · 4 PNG textures · 4 CUBE presets'}</p><p class="bundle-small">{'无需注册 · 允许商用 · 包含中英文使用说明' if zh else 'No sign-up · Commercial use permitted · Bilingual instructions included'}</p></div><a class="btn primary" href="{pack}" download>{'下载全部资源' if zh else 'Download the collection'} ↓ <span>{packsize}</span></a></div><div class="asset-tools" id="resources-luts"><div class="asset-filters" aria-label="{'资源类别' if zh else 'Resource category'}">{controls}</div><label class="asset-search"><span>{'搜索资源' if zh else 'Search resources'}</span><input id="resource-search" type="search" placeholder="{'如：海报、纹理、PSD' if zh else 'Try poster, texture or PSD'}"></label></div><p class="asset-result" aria-live="polite"><span id="resource-count">14</span> {'份资源' if zh else 'resources'} · <a href="#use">{'使用方法与授权' if zh else 'Usage & license'} ↗</a></p><div class="asset-grid">{''.join(cards)}</div><p id="resource-empty" class="no-results" hidden>{'没有匹配资源，请清除搜索词或切换分类。' if zh else 'No matches. Clear your search or try another category.'}</p><p class="source-note">{'文件结构与读取校验已完成；尚未在 PhotoCraft 应用内实测。PSD 示例文字为像素图层，SVG 为可选矢量源文件。' if zh else 'File structure and decoding checks completed; not tested inside PhotoCraft. PSD sample text is rasterized; SVG is an optional vector source.'}</p></section>'''
